@namespace sv_e149352c30a14061b46a814baf3df45f.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea Channel="_activeChannel"
                 Messages="_messages"
                 ThreadSummaries="_threadSummaries"
                 IsLoadingMore="_isLoadingMore"
                 OnLoadMore="LoadOlderMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = new();
    private List<Message> _messages = new();
    private List<ThreadSummary> _threadSummaries = new();
    private List<Message> _threadReplies = new();
    private Channel? _activeChannel;
    private int _activeChannelId;
    private Message? _threadRootMessage;
    private bool _threadOpen;
    private bool _isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _threadSummaries = BuildThreadSummaries(_messages);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            _channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore || _activeChannel is null) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _threadSummaries = BuildThreadSummaries(_messages);
        }
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary in the main message list
        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadReplies.Count);
    }

    private async Task HandleReaction(ReactionRequest request)
    {
        await ChatService.AddReactionAsync(request.MessageId, request.Emoji);

        // Update locally
        var msg = _messages.FirstOrDefault(m => m.Id == request.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == request.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(request.Emoji, new List<string> { "You" }));
            }
        }
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> messages, int? updatedRootId = null, int? updatedCount = null)
    {
        var roots = messages.Where(m => m.ReplyToId is null).ToList();
        var summaries = new List<ThreadSummary>();

        foreach (var root in roots)
        {
            var replies = messages.Where(m => m.ReplyToId == root.Id).ToList();
            if (replies.Count > 0 || (updatedRootId == root.Id && updatedCount > 0))
            {
                var count = updatedRootId == root.Id ? updatedCount!.Value : replies.Count;
                var lastReply = replies.Count > 0 ? replies.Max(r => r.SentAt) : DateTime.UtcNow;
                summaries.Add(new ThreadSummary(root.Id, count, lastReply));
            }
        }

        return summaries;
    }
}

